import copy, re, zipfile, shutil, os
from lxml import etree
WNS="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
W="{%s}"%WNS
XMLSP="{http://www.w3.org/XML/1998/namespace}space"
AUTHOR="Alderman & Kessler LLP (for Vantage)"
DATE="2025-05-06T09:00:00Z"
class Doc:
    def __init__(s, src_dir):
        s.dir=src_dir
        s.tree=etree.parse(os.path.join(src_dir,"word/document.xml"))
        s.body=s.tree.getroot().find(W+"body")
        s.rid=1000
        s.comments=[]
        s.paras=list(s.body.iter(W+"p"))
        s.tmpl={"body":s.ptext_find("Section 4.1")[1], "list":s.ptext_find("(a) Kerrigan-Holst Manufacturing Group, LLC shall bear")[1], "sched":s.ptext_find("Email: rkessler@aldermankessler.com")[1]}
        s.bold_rpr=None; s.norm_rpr=None
        p=s.tmpl["body"]
        rs=p.findall(W+"r"); s.bold_rpr=copy.deepcopy(rs[0].find(W+"rPr")); s.norm_rpr=copy.deepcopy(rs[1].find(W+"rPr"))
    def nid(s):
        s.rid+=1; return str(s.rid)
    @staticmethod
    def text(p):
        return "".join((t.text or "") for r in p.findall(W+"r") for t in r.findall(W+"t"))
    def ptext_find(s, needle, occ=1):
        n=0
        for i,p in enumerate(s.paras):
            if needle in s.text(p):
                n+=1
                if n==occ: return i,p
        raise Exception("not found: "+needle)
    def find(s, needle, occ=1):
        return s.ptext_find(needle,occ)[1]
    # --- tracked edit within paragraph
    def _mkrun(s, rpr, text, deleted=False):
        r=etree.Element(W+"r")
        if rpr is not None: r.append(copy.deepcopy(rpr))
        t=etree.SubElement(r, W+("delText" if deleted else "t")); t.set(XMLSP,"preserve"); t.text=text
        return r
    def _wrap(s, kind, runs):
        e=etree.Element(W+kind); e.set(W+"id",s.nid()); e.set(W+"author",AUTHOR); e.set(W+"date",DATE)
        for r in runs: e.append(r)
        return e
    @staticmethod
    def _shrink(old,new):
        to=re.findall(r"\s+|[^\s]+",old); tn=re.findall(r"\s+|[^\s]+",new)
        a=0
        while a<len(to) and a<len(tn) and to[a]==tn[a]: a+=1
        b=0
        while b<len(to)-a and b<len(tn)-a and to[-1-b]==tn[-1-b]: b+=1
        pre="".join(to[:a]); suf="".join(to[len(to)-b:]) if b else ""
        return len(pre), old[len(pre):len(old)-len(suf)], new[len(pre):len(new)-len(suf)]
    def edit(s, p, pairs, bold_ins=None):
        full=s.text(p)
        spans=[]
        for old,new in pairs:
            if old=="__BODY__":
                hb=s.heading_len(p); old=full[hb:]
            c=full.count(old)
            assert c==1, ("edit target count %d: %r"%(c,old[:80]))
            st=full.index(old)
            off,o2,n2=s._shrink(old,new)
            spans.append((st+off, st+off+len(o2), n2))
        spans.sort()
        runs=[r for r in p.findall(W+"r")]
        # build char->run map
        segs=[]; pos=0
        for r in runs:
            t="".join((x.text or "") for x in r.findall(W+"t"))
            segs.append((pos,pos+len(t),r.find(W+"rPr"),t)); pos+=len(t)
        def rpr_at(i):
            for a,b,rp,t in segs:
                if a<=i<b: return rp
            return segs[-1][2]
        newkids=[]
        cur=0
        def emit_plain(a,b,deleted=False):
            out=[]
            for sa,sb,rp,t in segs:
                x=max(a,sa); y=min(b,sb)
                if x<y: out.append(s._mkrun(rp,t[x-sa:y-sa],deleted))
            return out
        for (a,b,n) in spans:
            newkids+=emit_plain(cur,a)
            if b>a: newkids.append(s._wrap("del",emit_plain(a,b,True)))
            if n:
                rp=copy.deepcopy(rpr_at(a if a<len(full) else len(full)-1))
                if rp is not None:
                    bnode=rp.find(W+"b")
                    if bold_ins is False and bnode is not None: rp.remove(bnode)
                newkids.append(s._wrap("ins",[s._mkrun(rp,n)]))
            cur=b
        newkids+=emit_plain(cur,len(full))
        for r in runs: p.remove(r)
        for k in newkids: p.append(k)
    def heading_len(s,p):
        rs=p.findall(W+"r")
        if len(rs)>=2 and rs[0].find(W+"rPr") is not None and rs[0].find(W+"rPr").find(W+"b") is not None:
            return len("".join(t.text or "" for t in rs[0].findall(W+"t")))
        return 0
    def new_para(s, after, segments, tmpl="body"):
        p=etree.Element(W+"p")
        ppr=copy.deepcopy(s.tmpl[tmpl].find(W+"pPr")); p.append(ppr)
        rp=etree.SubElement(ppr,W+"rPr"); m=etree.SubElement(rp,W+"ins"); m.set(W+"id",s.nid()); m.set(W+"author",AUTHOR); m.set(W+"date",DATE)
        if isinstance(segments,str): segments=[(segments,False)]
        runs=[s._mkrun(s.bold_rpr if b else s.norm_rpr, t) for t,b in segments]
        p.append(s._wrap("ins",runs))
        after.addnext(p)
        return p
    def insert_after(s, anchor, paras):
        cur=anchor; out=[]
        for segs,tm in paras:
            cur=s.new_para(cur,segs,tm); out.append(cur)
        return out
    def delete_para(s,p):
        ppr=p.find(W+"pPr")
        rp=ppr.find(W+"rPr")
        if rp is None: rp=etree.SubElement(ppr,W+"rPr")
        m=etree.SubElement(rp,W+"del"); m.set(W+"id",s.nid()); m.set(W+"author",AUTHOR); m.set(W+"date",DATE)
        runs=p.findall(W+"r")
        dl=[]
        for r in runs:
            for t in r.findall(W+"t"): t.tag=W+"delText"
            p.remove(r); dl.append(r)
        p.append(s._wrap("del",dl))
    def comment(s,p,text):
        cid=str(len(s.comments)+1)
        s.comments.append((cid,text))
        st=etree.Element(W+"commentRangeStart"); st.set(W+"id",cid)
        ppr=p.find(W+"pPr")
        if ppr is not None: ppr.addnext(st)
        else: p.insert(0,st)
        en=etree.SubElement(p,W+"commentRangeEnd"); en.set(W+"id",cid)
        r=etree.SubElement(p,W+"r"); rpr=etree.SubElement(r,W+"rPr"); rs=etree.SubElement(rpr,W+"rStyle"); rs.set(W+"val","CommentReference")
        cr=etree.SubElement(r,W+"commentReference"); cr.set(W+"id",cid)
    def save(s,out):
        s.tree.write(os.path.join(s.dir,"word/document.xml"),xml_declaration=True,encoding="UTF-8",standalone=True)
        root=etree.Element(W+"comments",nsmap={"w":WNS})
        for cid,text in s.comments:
            c=etree.SubElement(root,W+"comment"); c.set(W+"id",cid); c.set(W+"author",AUTHOR); c.set(W+"date",DATE); c.set(W+"initials","A&K")
            for i,para in enumerate(text.split("\n")):
                pp=etree.SubElement(c,W+"p"); r=etree.SubElement(pp,W+"r")
                if i==0:
                    ref=etree.SubElement(r,W+"annotationRef"); r=etree.SubElement(pp,W+"r")
                t=etree.SubElement(r,W+"t"); t.set(XMLSP,"preserve"); t.text=para
        etree.ElementTree(root).write(os.path.join(s.dir,"word/comments.xml"),xml_declaration=True,encoding="UTF-8",standalone=True)
        ct=os.path.join(s.dir,"[Content_Types].xml"); x=open(ct).read()
        if "/word/comments.xml" not in x:
            x=x.replace("</Types>","<Override PartName=\"/word/comments.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml\"/></Types>"); open(ct,"w").write(x)
        rl=os.path.join(s.dir,"word/_rels/document.xml.rels"); x=open(rl).read()
        if "relationships/comments" not in x:
            x=x.replace("</Relationships>","<Relationship Id=\"rId99\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments\" Target=\"comments.xml\"/></Relationships>"); open(rl,"w").write(x)
        st=os.path.join(s.dir,"word/settings.xml"); x=open(st).read()
        if "trackRevisions" not in x:
            x=re.sub(r"(<w:settings[^>]*>)", r"\1<w:trackRevisions/>", x, count=1); open(st,"w").write(x)
        with zipfile.ZipFile(out,"w",zipfile.ZIP_DEFLATED) as z:
            ctp="[Content_Types].xml"; z.write(os.path.join(s.dir,ctp),ctp)
            for dp,dn,fn in os.walk(s.dir):
                for f in fn:
                    full=os.path.join(dp,f); rel=os.path.relpath(full,s.dir)
                    if rel==ctp: continue
                    z.write(full,rel)
